$(function(){navigation()});var navigation=function(){var e=$(".js-header");$(".js-header-menu").on("click",function(){e.toggleClass("active")})},smoothscroll=function(){$('a[href^="#"]').click(function(){var e=$(this).attr("href"),e=$("#"==e||""==e?"html":e).offset().top;return $("html, body").animate({scrollTop:e},500,"swing"),!1})},swiper=new Swiper(".swiper",{loop:!0,speed:1500,slidesPerView:1,spaceBetween:90,centeredSlides:!0,breakpoints:{751:{slidesPerView:1.5,spaceBetween:90,centeredSlides:!0}},autoplay:{delay:1e3,disableOnInteraction:!1},navigation:{nextEl:".swiper-button-next",prevEl:".swiper-button-prev"}});